const isSameCell = ([x, y]: Cell, [otherX, otherY]: Cell): boolean =>
  x === otherX && y === otherY;

const isNeighborOf = ([x, y]: Cell, [otherX, otherY]: Cell): boolean =>
  Math.abs(x - otherX) <= 1 && Math.abs(y - otherY) <= 1;

function countLiveNeighbors(cell: Cell, liveCells: Cell[]): number {
  return liveCells.filter(
    (other) => !isSameCell(cell, other) && isNeighborOf(cell, other),
  ).length;
}

const survives = (neighbors: number): boolean =>
  neighbors >= MIN_NEIGHBORS_TO_SURVIVE &&
  neighbors <= MAX_NEIGHBORS_TO_SURVIVE;

export function nextGeneration(liveCells: Cell[]): Cell[] {
  return liveCells.filter((cell) => survives(countLiveNeighbors(cell, liveCells)));
}
